def to_cuda(batch, device="cuda", ignore_list: List[str] = []) -> torch.Tensor:

    """
    Converts the input batch to a CUDA tensor, recursively handling nested structures like tuples, lists, and dictionaries, except for dictionary keys named in the ignore_list. It ensures that the data is moved to the specified CUDA device for GPU processing.
    Input-Output Arguments
    :param batch: tuple, list, dict, torch.Tensor, or other. The input data that needs to be converted to a CUDA tensor. It supports nested structures and handles them accordingly.
    :param device: str, default "cuda". The target CUDA device to which the data will be moved.
    :param ignore_list: List[str], default []. A list of keys to ignore when moving data to the CUDA device.
    :return: torch.Tensor. The input batch converted to a CUDA tensor, ready for GPU processing.
    """
    if isinstance(batch, dict):
        new_batch = {k: to_cuda(v, device, ignore_list) if v is not None else None for k, v in batch.items() if k not in ignore_list}
        for k, v in new_batch.items():
            if "meta" in k:
                new_batch[k] = dotdict(v)
        return new_batch
    elif isinstance(batch, (tuple, list)):
        return type(batch)(to_cuda(b, device, ignore_list) for b in batch)
    elif isinstance(batch, torch.Tensor):
        if "meta" in batch.keys() and "meta" not in ignore_list:
            batch = {k: v for k, v in batch.items() if k != "meta"}
        return batch.to(device)
    else:
        return batch
